#include <bits/stdc++.h>
using namespace std;

const int N = 100, D = 31, MOD = 1000000007;

int base_d, index, digits[N];
long long number;

struct Matrix {
    long long matrix_data[D][D];

    Matrix() {
        for (int i = 0; i <= base_d; i++) {
            for (int j = 0; j <= base_d; j++) {
                matrix_data[i][j] = 0;
            }
        }
    }

    Matrix operator*(const Matrix& other) const {
        Matrix result;
        for (int i = 0; i <= base_d; i++) {
            for (int j = 0; j <= base_d; j++) {
                for (int k = 0; k <= base_d; k++) {
                    result.matrix_data[i][j] = (result.matrix_data[i][j] + matrix_data[i][k] * other.matrix_data[k][j]) % MOD;
                }
            }
        }
        return result;
    }
} base_matrices[N];

Matrix rotate_matrix(int shift) {
    shift = (shift + base_d) % base_d;
    Matrix m;
    for (int i = 0; i < base_d; i++) {
        m.matrix_data[i][(i + shift) % base_d] = 1;
    }
    m.matrix_data[base_d][base_d] = 1;
    return m;
}

void initialize() {
    for (int i = 1; i < base_d; i++) {
        base_matrices[0].matrix_data[i][i] = 1;
    }
    base_matrices[0].matrix_data[base_d][0] = 1;
    base_matrices[0].matrix_data[base_d][base_d] = 2;
    base_matrices[0].matrix_data[0][base_d] = -1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> number >> base_d;
    for (index = 0; number > 0; index++, number /= base_d) {
        digits[index] = number % base_d;
    }
    initialize();
    for (int i = 1; i < index; i++) {
        base_matrices[i] = rotate_matrix(0);
        for (int j = 0; j < base_d; j++) {
            base_matrices[i] = base_matrices[i] * base_matrices[i - 1] * rotate_matrix(1);
        }
    }
    Matrix answer = rotate_matrix(0);
    for (int i = index - 1; i >= 0; i--) {
        for (int j = 0; j < digits[i]; j++) {
            answer = answer * base_matrices[i] * rotate_matrix(1);
        }
    }
    cout << (answer.matrix_data[base_d][base_d] + MOD) % MOD;
}
